<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const mapping=ref<components['schemas']['MemoryTasks']>({});const items=ref<components['schemas']['MemoryItem'][]>([]);const error=ref('');onMounted(async()=>{try{mapping.value=requireData(await client.GET('/api/admin/memory/tasks'));items.value=requireData(await client.GET('/api/admin/memory'))}catch(cause){error.value=errorMessage(cause)}});async function save(){try{requireData(await client.PUT('/api/admin/memory/tasks',{body:mapping.value}))}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="任务记忆映射" description="每个任务注入总量不得超过 5KB。"/><p v-if="error" class="text-danger">{{ error }}</p><form class="grid gap-5" @submit.prevent="save"><fieldset v-for="(_,task) in mapping" :key="task" class="rounded-card border border-border p-4"><legend class="font-semibold">{{ task }}</legend><label v-for="item in items" :key="item.id" class="me-4 inline-flex gap-2"><input v-model="mapping[task]" type="checkbox" :value="item.id">{{ item.title }}</label></fieldset><button class="nw-button">保存映射</button></form></template>
